func expectStamp(mock sqlmock.Sqlmock, now time.Time, already bool) {
	claim := mock.ExpectQuery(`(?s)UPDATE sites.*handed_over_at IS NULL`)
	if already {
		claim.WillReturnRows(sqlmock.NewRows([]string{"handed_over_at", "live_link_expires_at", "transfer_confirmed"}))
		mock.ExpectQuery(`SELECT handed_over_at`).
			WillReturnRows(...AddRow(now.UTC(), now.UTC().Add(LiveLinkWindow), false))
		return
	}
	claim.WillReturnRows(...AddRow(now.UTC(), now.UTC().Add(LiveLinkWindow), false))
}
